def transform(grid):
    h, w = len(grid), len(grid[0])
    projections = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: c - r,
        lambda r, c: r + c,
    ]

    candidates = []
    for proj in projections:
        lines = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    lines.setdefault(proj(r, c), set()).add(color)

        if lines and all(len(colors) == 1 for colors in lines.values()):
            score = sum(
                sum(1 for r in range(h) for c in range(w)
                    if grid[r][c] and proj(r, c) == key) ** 2
                for key in lines
            )
            candidates.append((score, proj, {k: next(iter(v)) for k, v in lines.items()}))

    if not candidates:
        return [row[:] for row in grid]

    _, proj, known = max(candidates, key=lambda item: item[0])
    lo, hi = min(known), max(known)
    period = hi - lo + 1
    for p in range(1, hi - lo + 2):
        residue_colors = {}
        valid = True
        for key, color in known.items():
            residue = key % p
            if residue in residue_colors and residue_colors[residue] != color:
                valid = False
                break
            residue_colors[residue] = color
        if valid:
            period = p
            break

    residue_colors = {}
    for key, color in known.items():
        residue_colors[key % period] = color

    residues = list(residue_colors)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            residue = proj(r, c) % period
            if residue not in residue_colors:
                nearest = min(residues, key=lambda x: min((x - residue) % period, (residue - x) % period))
                row.append(residue_colors[nearest])
            else:
                row.append(residue_colors[residue])
        out.append(row)
    return out
